b2_add = [
    make_q("sd5-b2-5", "Dasar", "Faktor persekutuan terbesar (FPB) dari 12 dan 18 adalah...", ["6", "4", "3", "2"], "A", "Faktor 12: 1, 2, 3, 4, 6, 12. Faktor 18: 1, 2, 3, 6, 9, 18. Yang terbesar adalah 6.", "**Langkah Penyelesaian Terstruktur:**\\nFPB(12, 18) = **6** (Opsi A)."),
    make_q("sd5-b2-6", "Sedang", "Kelipatan persekutuan terkecil (KPK) dari 15 dan 20 adalah...", ["60", "30", "45", "120"], "A", "KPK diperoleh dari perkalian faktor prima pangkat tertinggi: $2^2 \\times 3 \\times 5$.", "**Langkah Penyelesaian Terstruktur:**\\n$$15 = 3 \\times 5, \\quad 20 = 2^2 \\times 5 \\implies \\text{KPK} = 4 \\times 3 \\times 5 = 60$$ (Opsi A)."),
    make_q("sd5-b2-7", "Sedang", "Faktorisasi prima dari bilangan 72 adalah...", ["2^3 \\times 3^2", "2^2 \\times 3^3", "2^4 \\times 3", "2 \\times 3^3"], "A", "Bagi 72 dengan bilangan prima berturut-turut: $72 : 2 = 36 : 2 = 18 : 2 = 9 : 3 = 3$.", "**Langkah Penyelesaian Terstruktur:**\\n$$72 = 2^3 \\times 3^2$$ (Opsi A)."),
    make_q("sd5-b2-8", "Sedang", "FPB dari 24, 36, dan 48 adalah...", ["12", "6", "8", "24"], "A", "Faktor prima yang sama berpangkat terendah: $2^2 \\times 3 = 12$.", "**Langkah Penyelesaian Terstruktur:**\\nFPB(24, 36, 48) = **12** (Opsi A)."),
    make_q("sd5-b2-9", "Sedang", "KPK dari 12, 18, dan 24 adalah...", ["72", "48", "96", "144"], "A", "Faktor prima: $12 = 2^2 \\times 3, 18 = 2 \\times 3^2, 24 = 2^3 \\times 3$. KPK $= 2^3 \\times 3^2 = 72$.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\text{KPK} = 8 \\times 9 = 72$$ (Opsi A)."),
    make_q("sd5-b2-10", "Sedang", "Lampu A menyala setiap 6 detik sekali dan lampu B menyala setiap 8 detik sekali. Jika kedua lampu menyala bersamaan pada detik ke-0, pada detik ke berapa kedua lampu akan menyala bersamaan lagi untuk pertama kali?", ["24", "48", "14", "18"], "A", "Cari KPK dari 6 dan 8.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\text{KPK}(6, 8) = 24\\text{ detik}$$ (Opsi A)."),
    make_q("sd5-b2-11", "Sedang", "Ibu memiliki 30 kue bolu dan 45 kue sus. Kue tersebut akan dimasukkan ke dalam beberapa piring sama banyak. Berapa piring paling banyak yang dibutuhkan ibu?", ["15 piring", "10 piring", "5 piring", "9 piring"], "A", "Cari FPB dari 30 dan 45.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\text{FPB}(30, 45) = 15\\text{ piring}$$ (Opsi A)."),
    make_q("sd5-b2-12", "Sedang", "Beni berenang setiap 4 hari sekali dan Danu berenang setiap 6 hari sekali di kolam yang sama. Jika mereka berenang bersama pada hari Senin, pada hari apa mereka akan berenang bersama lagi berikutnya?", ["Sabtu", "Jumat", "Minggu", "Senin"], "A", "KPK(4, 6) = 12 hari. Senin + 12 hari = Senin + 5 hari = Sabtu.", "**Langkah Penyelesaian Terstruktur:**\\n1. KPK(4, 6) = 12 hari\\n2. 12 hari setelah Senin: Senin + 7 hari (Senin) + 5 hari = **Sabtu** (Opsi A)."),
    make_q("sd5-b2-13", "Sedang", "Seorang guru memiliki 24 buku tulis dan 36 pulpen untuk dibagikan kepada siswanya sama rata. Berapakah banyak buku tulis yang diterima setiap siswa jika dibagikan ke siswa sebanyak-banyaknya?", ["2 buku tulis", "3 buku tulis", "4 buku tulis", "6 buku tulis"], "A", "Banyak siswa $= \\text{FPB}(24, 36) = 12$. Buku per siswa $= 24 : 12 = 2$.", "**Langkah Penyelesaian Terstruktur:**\\n$$24 : \\text{FPB}(24, 36) = 24 : 12 = 2\\text{ buku tulis}$$ (Opsi A)."),
    make_q("sd5-b2-14", "Sedang", "Bilangan prima yang terletak di antara 20 dan 30 adalah...", ["23 dan 29", "21 dan 27", "23 dan 27", "21 dan 29"], "A", "Bilangan prima hanya memiliki 2 faktor (1 dan dirinya sendiri).", "**Langkah Penyelesaian Terstruktur:**\\nBilangan prima antara 20 dan 30 adalah **23 dan 29** (Opsi A)."),
    make_q("sd5-b2-15", "Sedang", "KPK dan FPB dari bilangan 36 dan 60 berturut-turut adalah...", ["180 dan 12", "120 dan 12", "180 dan 6", "360 dan 12"], "A", "$36 = 2^2 \\times 3^2$, $60 = 2^2 \\times 3 \\times 5$. KPK $= 180$, FPB $= 12$.", "**Langkah Penyelesaian Terstruktur:**\\nKPK = 180 dan FPB = 12 (Opsi A)."),
    make_q("sd5-b2-16", "Tantangan", "Tiga buah jam weker berdering bersamaan pada pukul 07.00. Weker pertama berdering setiap 15 menit, weker kedua setiap 20 menit, dan weker ketiga setiap 30 menit. Pada pukul berapakah ketiga weker akan berdering bersamaan lagi untuk kedua kalinya?", ["08.00", "08.30", "09.00", "07.45"], "A", "KPK(15, 20, 30) = 60 menit (1 jam). Pukul 07.00 + 1 jam = 08.00.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\text{KPK}(15, 20, 30) = 60\\text{ menit} = 1\\text{ jam} \\implies 07.00 + 1\\text{ jam} = 08.00$$ (Opsi A)."),
    make_q("sd5-b2-17", "Tantangan", "Pak Ahmad memiliki 48 bibit mangga, 72 bibit jeruk, dan 96 bibit rambutan. Bibit tersebut akan ditanam di beberapa petak kebun dengan jumlah bibit tiap jenis sama banyak. Berapa jumlah seluruh bibit di setiap petak kebun?", ["9 bibit", "8 bibit", "10 bibit", "12 bibit"], "A", "Banyak petak $= \\text{FPB}(48, 72, 96) = 24$. Total bibit per petak $= (48 + 72 + 96) : 24 = 216 : 24 = 9$.", "**Langkah Penyelesaian Terstruktur:**\\n1. FPB(48, 72, 96) = 24 petak\\n2. Tiap petak: $\\frac{48 + 72 + 96}{24} = \\frac{216}{24} = 9\\text{ bibit}$ (Opsi A)."),
    make_q("sd5-b2-18", "Tantangan", "Dua bilangan memiliki FPB 14 dan KPK 84. Jika salah satu bilangan adalah 28, maka bilangan yang lainnya adalah...", ["42", "56", "36", "48"], "A", "Gunakan sifat: Bilangan $A \\times B = \\text{FPB} \\times \\text{KPK}$.", "**Langkah Penyelesaian Terstruktur:**\\n$$B = \\frac{\\text{FPB} \\times \\text{KPK}}{A} = \\frac{14 \\times 84}{28} = \\frac{84}{2} = 42$$ (Opsi A)."),
    make_q("sd5-b2-19", "Tantangan", "Toko sembako menerima kiriman telur setiap 8 hari, minyak goreng setiap 12 hari, dan gula pasir setiap 16 hari. Pada tanggal 1 Maret mereka menerima ketiga barang bersamaan. Pada tanggal berapa mereka akan menerima ketiga barang bersamaan lagi?", ["18 April", "25 April", "1 Mei", "24 April"], "A", "KPK(8, 12, 16) = 48 hari. Maret ada 31 hari. Sisa hari Maret: $31 - 1 = 30$ hari. April: $48 - 30 = 18$ April.", "**Langkah Penyelesaian Terstruktur:**\\n1. KPK(8, 12, 16) = 48 hari\\n2. Tanggal: 1 Maret + 48 hari = 18 April (Opsi A)."),
    make_q("sd5-b2-20", "Tantangan", "Ibu membuat 54 kue lemper, 72 kue lapis, dan 90 kue pastel untuk disajikan dalam beberapa piring. Berapa selisih banyaknya kue pastel dan kue lemper pada masing-masing piring?", ["2 buah", "3 buah", "1 buah", "4 buah"], "A", "Piring $= \\text{FPB}(54, 72, 90) = 18$. Pastel $= 90 / 18 = 5$. Lemper $= 54 / 18 = 3$. Selisih $= 5 - 3 = 2$.", "**Langkah Penyelesaian Terstruktur:**\\n1. FPB(54, 72, 90) = 18 piring\\n2. Pastel per piring: $90 : 18 = 5$\\n3. Lemper per piring: $54 : 18 = 3$\\n4. Selisih $= 5 - 3 = 2\\text{ buah}$ (Opsi A).")
]

