    make_q("sd5-b3-6", "Sedang", "Hasil penjumlahan $\\frac{2}{3} + \\frac{1}{4}$ adalah...", ["\\frac{11}{12}", "\\frac{3}{7}", "\\frac{5}{12}", "\\frac{7}{12}"], "A", "Samakan penyebut dengan KPK dari 3 dan 4 yaitu 12: $\\frac{8}{12} + \\frac{3}{12}$.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\frac{8 + 3}{12} = \\frac{11}{12}$$ (Opsi A)."),
