    make_q("sd5-b3-11", "Sedang", "Ibu membeli gula pasir seberat $3\\frac{1}{4}\\text{ kg}$. Ibu menggunakan $1\\frac{1}{2}\\text{ kg}$ untuk membuat sirup. Sisa gula pasir ibu adalah...", ["1\\frac{3}{4}\\text{ kg}", "1\\frac{1}{4}\\text{ kg}", "2\\frac{1}{4}\\text{ kg}", "1\\frac{1}{2}\\text{ kg}"], "A", "$3\\frac{1}{4} - 1\\frac{2}{4} = 2\\frac{5}{4} - 1\\frac{2}{4} = 1\\frac{3}{4}$.", "**Langkah Penyelesaian Terstruktur:**\\n$$3\\frac{1}{4} - 1\\frac{2}{4} = 1\\frac{3}{4}\\text{ kg}$$ (Opsi A)."),
    make_q("sd5-b3-12", "Sedang", "Pak Doni memiliki sebidang tanah seluas 600 meter persegi. $\\frac{2}{5}$ bagian ditanami jagung dan sisanya ditanami kedelai. Luas tanah yang ditanami kedelai adalah...", ["360 m^2", "240 m^2", "300 m^2", "400 m^2"], "A", "Bagian kedelai $= 1 - 2/5 = 3/5$. Luas $= \\frac{3}{5} \\times 600 = 360$.", "**Langkah Penyelesaian Terstruktur:**\\n$$\\frac{3}{5} \\times 600 = 360\\text{ m}^2$$ (Opsi A)."),
